    @classmethod
    def from_chain_file(cls, path: str) -> "EvidenceStore":
        """Load from an existing chain JSON file."""
        chain = VerificationChain.load_json(path)
        # Infer experiment name from directory or filename
        p = Path(path)
        experiment = p.parent.name if p.parent.name != "." else p.stem
        return cls(chain, experiment)

def _classify_event(rec: EvidenceRecord, finding_id: str) -> str:
    """Classify a record's relationship to a finding."""
    atype = rec.artifact_type

    if atype == "model_chat_log":
        # Check if this is a submission or a verdict
        if rec.payload and isinstance(rec.payload, dict):
            payload_str = json.dumps(rec.payload)
            if f"CONFIRM {finding_id}" in payload_str:
                return "confirmed"
            if f"CHALLENGE {finding_id}" in payload_str:
                return "challenged"
            if f"EXTEND {finding_id}" in payload_str:
                return "extended"
            if f"MERGE {finding_id}" in payload_str:
                return "merged"
        return "submitted"

    if atype == "experiment_report":
        return "reported"

    if atype == "experiment_checkpoint":
        return "checkpoint"

    if atype == "health_scan":
        return "health_scan"

    if atype == "policy_snapshot":
        return "policy"

    if atype == "verdict":
        return "verdict"

    return "referenced"

def verify_inclusion_proof(self, proof: dict, merkle_root: str) -> bool:
        """Verify an inclusion proof against a given Merkle root.

        merkle_root should be in 'sha256:<hex>' format. If the proof embeds a
        merkle_root field, it must match the supplied root.
        """
        try:
            if "merkle_root" in proof and proof["merkle_root"] != merkle_root:
                return False
            leaf_data = _digest_bytes(proof["chain_hash"])
            root_bytes = _digest_bytes(merkle_root)
            return rfc9162_verify_inclusion(leaf_data, proof["proof"], root_bytes)
        except (KeyError, ValueError, TypeError):
            return False

    def build_inclusion_proof(self, index: int) -> dict:
        """Build an RFC 9162 inclusion proof for the record at `index`."""
        if not (0 <= index < len(self._records)):
            raise IndexError(
                f"Index {index} out of range [0, {len(self._records)})"
            )
        leaves = [_digest_bytes(r["chain_hash"]) for r in self._records]
        proof_steps = rfc9162_inclusion_proof(leaves, index)
        root = rfc9162_merkle_root(leaves)
        return {
            "chain_hash": self._records[index]["chain_hash"],
            "proof": proof_steps,
            "merkle_root": "sha256:" + root.hex(),
        }
